      const newsHeadline=e=>e.title.includes(nationName(e))?e.title:nationName(e)+': '+e.title;
      if(!bulletins.some(e=>e.id===ui.newsId))ui.newsId=bulletins[0]?.id;
      const event=bulletins.find(e=>e.id===ui.newsId)||examples[0],mediaLibrary=globalThis.SpaceRaceNewsMedia||{},imageKey=bulletinMediaKey(event);
