      const media=mediaLibrary[imageKey]||(['lunar','earth'].includes(imageKey)?conceptMedia:mediaLibrary['mission-control']);
      $('#sp-news-select').innerHTML=bulletins.map(e=>'<option value="'+esc(e.id)+'">'+esc((e.example?'Example · ':e.date+' · ')+newsHeadline(e))+'</option>').join('');$('#sp-news-select').value=event.id;
      const rewards=event.rewardEffects||{},signed=n=>(n>0?'+':'')+Number(n||0).toFixed(Number.isInteger(Number(n||0))?0:1),effects=[];
      if(rewards.prestige)effects.push('<span>Prestige <b>'+signed(rewards.prestige)+'</b></span>');
      if(rewards.researchPoints)effects.push('<span>Research data <b>'+signed(rewards.researchPoints)+'</b></span>');
      if(rewards.politicalCapital)effects.push('<span>Political capital <b>'+signed(rewards.politicalCapital)+'</b></span>');
      if(event.crewFatalities)effects.push('<span>Crew fatalities <b>'+esc(event.crewFatalities)+'</b></span>');
      if(event.investigationMonths)effects.push('<span>Technical investigation <b>'+esc(event.investigationMonths)+' months</b></span>');
      const country=nationName(event),headline=newsHeadline(event);
      const bulletinLabel=event.scope==='world'?'WORLD NEWS · '+(event.firstMilestone?'WORLD FIRST CONFIRMED':event.majorNationalAchievement?'NATIONAL MILESTONE CONFIRMED':'MAJOR SPACEFLIGHT EVENT'):'NATIONAL SPACE AUTHORITY · '+(event.kind==='programme'?'PROGRAMME BULLETIN':'MISSION REPORT');
      $('[data-news-bulletin]').innerHTML='<article class="sp-newsarticle"><div class="sp-news-masthead">INTERNATIONAL NEWS SERVICE</div><div class="sp-news-status">'+(event.example?'ILLUSTRATIVE BULLETIN · NO CAMPAIGN EFFECT':bulletinLabel)+'</div><h3>'+esc(headline)+'</h3><div class="sp-news-meta">'+esc(event.date)+' · '+esc(country)+' · '+(event.scope==='world'?'International bulletin':'National bulletin')+'</div>'+(media?'<figure><img src="'+media.src+'" alt="'+esc(headline)+'" /></figure>':'')+'<p>'+esc(event.description)+'</p><div class="sp-news-effects">'+(effects.join('')||'<span>'+(event.kind==='programme'?'Programme':'Mission')+' record updated</span>')+'</div><button type="button" class="sp-action cursor-interaction" data-news-ack>'+(event.crewFatalities?'Honour the Crew':'Acknowledge the Report')+'</button></article>';
      $('[data-news-count]').textContent=events.length+' bulletins';$('[data-news-list]').innerHTML=events.map(e=>'<div class="sp-entry"><div><b>'+esc(newsHeadline(e))+'</b><p>'+esc(e.date)+' · '+esc(nationName(e))+' · '+(e.scope==='world'?'World news':'National report')+'</p></div><button type="button" class="sp-smallbutton cursor-interaction" data-news="'+esc(e.id)+'">Read</button></div>').join('')||'<p class="sp-empty">Programme decisions, qualification milestones, launches and mission results appear here.</p>';
      $('[data-world-firsts]').innerHTML=(catalogue.milestones||[]).map(m=>{const receipt=s.worldFirsts?.[m.id];return'<li>'+esc(m.title)+' — '+(receipt?esc(nationName(receipt))+' · '+esc(receipt.date):'Open competition')+'</li>';}).join('');
